head.script:
scwin.add = function(x, y, width, height) {
    var widget = widgetContainer1.addWidgets({
        title: "widget" + scwin.wcount,
        titleClass: "w2widget_orange",
        src: "widgetContainer_WPF-1476_(WSQ-2446)_widget.xml",
        scope: true,
        x: x,
        y: y,
        unitWidth: width,
        unitHeight: height,
        params: "USER_DATA"
    });
    scwin.wcount++;
};
scwin.resize = function(widgetId, width, height) {
    var widget = widgetContainer1.resizeWidget(widgetId, width, height);
}
scwin.t1_onclick = function() {
    scwin.add(i++, 0, 1, 1);
};
scwin.onclickcustombtn = function() {
